class Device(object):
    _vendor = None
    _model = None
    _version = None

    def __init__(self, **kwargs):
        pass

    @classmethod
    def get_vendor(cls):
        return cls._vendor

    @classmethod
    def get_model(cls):
        return cls._model

    @classmethod
    def get_version(cls):
        return cls._version
